##REVC
print(f"\nREVC: ")

REVC_seq = ""

def reverse_complement(REVC_seq):
    complement = str.maketrans("ATCG", "TAGC")
    return REVC_seq.translate(complement)[::-1]

print(reverse_complement(REVC_seq))

##FIB
print(f"\nFIB: ")

fib_1 = 29
fib_2 = 2

def fibonacci_rabbits(n, k):
    if n == 1 or n == 2:
        return 1
    
    f1, f2 = 1, 1
    
    for _ in range(3, n + 1):
        f1, f2 = f2, f2 + k * f1
        
    return f2

result = fibonacci_rabbits(fib_1, fib_2)
print(f"Total of pairs after {fib_2} months: {result}")

##GC
print(f"\nGC: ")

from pathlib import Path

fasta_arquivo = Path(__file__).with_name("rosalind_gc.txt")
sequences = []
sequence_name = None
sequence_parts = []

with open(fasta_arquivo, "r") as fasta_file:
    for line in fasta_file:
        line = line.strip()
        if not line:
            continue
        if line.startswith(">"):
            if sequence_name is not None:
                sequences.append((sequence_name, "".join(sequence_parts)))
            sequence_name = line[1:]
            sequence_parts = []
        else:
            sequence_parts.append(line)

if sequence_name is not None:
    sequences.append((sequence_name, "".join(sequence_parts)))

gc_percentages = [
    (name, (sequence.count("G") + sequence.count("C")) / len(sequence) * 100)
    for name, sequence in sequences
    if sequence
]

if not gc_percentages:
    raise ValueError(f"No FASTA sequences found in {fasta_arquivo}")

for name, percentage in gc_percentages:
    print(f"{name}: {percentage:.6f}% GC")

highest_name, highest_percentage = max(gc_percentages, key=lambda item: item[1])
print(f"\nHighest GC content: {highest_name}")
print(f"GC Percentage: {highest_percentage:.6f}%")

##HAMM
print(f"\nHAMM: ")

seq_hamm_1 = ""
seq_hamm_2 = ""

def hamming_distance(seq_hamm_1,seq_hamm_2):
    return sum(c1 != c2 for c1, c2 in zip(seq_hamm_2, seq_hamm_1))

result = hamming_distance(seq_hamm_1,seq_hamm_2)
print(f"Hamming distance is: {result}")

##IPRB
print(f"\nIPRB: ")

def probability_dominant(k, m, n):
    """
    k: int - Homozygous dominant (AA)
    m: int - Heterozygous (Aa)
    n: int - Homozygous recessive (aa)
    """
    T = k + m + n
    
    total_pairs = T * (T - 1)
    
    recessive_Aa_Aa = m * (m - 1) * 0.25
    recessive_Aa_aa = m * n * 0.5 * 2  # 2 caminhos: (Aa, aa) e (aa, Aa)
    recessive_aa_aa = n * (n - 1) * 1.0
    
    prob_recessivo = (recessive_Aa_Aa + recessive_Aa_aa + recessive_aa_aa) / total_pairs
    
    prob_dominante = 1 - prob_recessivo
    
    return prob_dominante

k, m, n = 27, 29, 27
resultado = probability_dominant(k, m, n)
print(f"Probabilidade: {resultado:.5f}")

