##SUBS
print(f"\nSUBS: ")

def find_motif(s, t):
    positions = []
    t_len = len(t)
    for i in range(len(s) - t_len + 1):
        if s[i : i + t_len] == t:
            positions.append(str(i + 1))
    return " ".join(positions)

s = ""
t = "TGAAGACTG"
print(find_motif(s, t))